import static org.jlinalg.cli.Monocle131ModelRequest.*;

/** Original Monocle1.3.7/Batchelor1.20 integration pipeline and native ordering verification. */
public final class Monocle137WorkflowCli {
    private Monocle137WorkflowCli() { }
    static final String RESOURCE="/org/jlinalg/omics/monocle137-workflow/";
    static final String SCOPE="Original Monocle3 1.3.7 preprocessing, Batchelor 1.20.0 reducedMNN alignment, aligned UMAP, clustering, graph learning and explicitly rooted ordering on complete prepared expression/metadata. Native Java verifies supplied graph distances and root selection; it does not replace original MNN/UMAP learning. Other original controls retain their pinned-source defaults. Original align_cds resets its seed to2016; no adapter seed override is inserted. Selected official source candidates do not establish the paper's executed commits or unreported settings. Standalone development component; no whole-tool, study reproduction or biological root certification.";
    static final String ACTION="Required action: read analysis-status.json and WARNINGS.md first; require pipeline_admitted=true for learned output and result_admitted=true for pseudotime. Retain complete inputs, both original source trees, models, RNG, process receipts and failed attempts. Supply the exact separate qualified Linux R4.3.3/Monocle3 1.3.7/Batchelor1.20.0 runtime. Install/download only where permitted; missing or forbidden runtime/install/execution is SKIP3 and dependent analysis is skipped. FAIL2 admits no partial result: resolve the named source, input, original-method, numeric or capacity error and retry NEW paths. Declare actual expression units and normalization; never infer batches/roots, repair labels, replace NA/Inf, silently switch editions or omit cells to force success. LEARN admits no pseudotime: inspect its graph, declare roots and use expected_principal_graph_sha256 on a matching RUN refit. Portable audit checks supplied graph ordering only; it does not refit the pipeline, reload RDS or authenticate producers. RDS checks cover complete required scientific state, not recreated igraph caches or all external nearest-neighbor pointers.";
    private static final class Skipped extends IOException {private static final long serialVersionUID=1L;Skipped(String s){super(s);}}
    public static void main(String[] args){int code=run(args,System.out,System.err);if(code!=0)System.exit(code);}
    public static int run(String[] args,PrintStream stdout,PrintStream stderr){
        Path out=null;boolean owned=false,pipeline=false,result=false;int code=2;String cause="Input validation",originalWarningText="";
        try{
            if(args.length==1&&args[0].equals("--help")){stdout.println("monocle137-workflow --request UTF8_JSON\nmonocle137-workflow --audit-graph PREPARED_GRAPH_JSON --out NEW_DIRECTORY\nTyped LEARN/RUN schema1; exact version1.3.7/batchelor_version1.20.0; complete TSV|MATRIX_MARKET expression, explicit units/provenance/population, cells/genes TSV, metadata_types, seed, preprocessing/alignment/reduction/clustering/graph settings, explicit RUN roots, rscript/r_libraries, monocle_source_root/batchelor_source_root, execution_policy ALLOW|FORBID, NEW out.\n"+SCOPE+"\n"+ACTION);return 0;}
            if(args.length==4&&args[0].equals("--audit-graph")&&args[2].equals("--out")){
                Path input=Path.of(args[1]).toAbsolutePath().normalize();out=Path.of(args[3]).toAbsolutePath().normalize();newOutput(out,List.of(input));owned=true;var pin=NextflowFiles.pin(input,268435456,()->{});byte[] raw=NextflowFiles.bytes(input,268435456);require(pin.equals(new NextflowFiles.Pin(raw.length,NextflowFiles.sha(raw))),"Graph changed during capture");Files.write(out.resolve("prepared-graph.json"),raw,StandardOpenOption.CREATE_NEW);var audit=Monocle137GraphAudit.audit(object(NextflowParameters.parse(NextflowFiles.utf8(raw),268435456,20000000)),1000000000);same(input,pin);NextflowFiles.writeJson(out.resolve("native-audit.json"),audit);cause="PASS_NATIVE_SUPPLIED_MONOCLE137_GRAPH_COMPARISON_ONLY";code=0;
            }else{
                require(args.length==2&&args[0].equals("--request"),"Require --request JSON, --audit-graph PATH --out NEW or --help");Path request=Path.of(args[1]).toAbsolutePath().normalize();var requestPin=NextflowFiles.pin(request,1048576,()->{});byte[] raw=NextflowFiles.bytes(request,1048576);require(requestPin.equals(new NextflowFiles.Pin(raw.length,NextflowFiles.sha(raw))),"Request changed during capture");var m=object(NextflowParameters.parse(NextflowFiles.utf8(raw),1048576,100000));var r=Monocle137WorkflowRequest.parse(m,request.getParent());out=r.out();var paths=new ArrayList<>(List.of(request,r.expression(),r.cells(),r.genes(),r.rscript(),r.monocleSource(),r.batchelorSource()));paths.addAll(r.libraries());newOutput(out,paths);owned=true;Files.write(out.resolve("source-request.json"),raw,StandardOpenOption.CREATE_NEW);
                if(!r.execute())throw new Skipped("Declared execution FORBID; no original analysis launched");if(!System.getProperty("os.name").equals("Linux"))throw new Skipped("Original integration/trajectory pipeline requires Linux Java");if(!Files.isExecutable(r.rscript()))throw new Skipped("Missing permitted Rscript: "+r.rscript());for(Path p:r.libraries())if(!Files.isDirectory(p))throw new Skipped("Missing declared R library: "+p);for(Path p:List.of(r.monocleSource(),r.batchelorSource()))if(!Files.isDirectory(p))throw new Skipped("Missing original source tree: "+p);
                var profile=object(NextflowParameters.parse(NextflowFiles.utf8(resource("source-profile.json")),1048576,200000));var sources=new LinkedHashMap<Path,Map<String,NextflowFiles.Entry>>();Path captured=Files.createDirectory(out.resolve("source"));
                for(var e:Map.of("monocle3",r.monocleSource(),"batchelor",r.batchelorSource()).entrySet()){
                    var tree=NextflowFiles.tree(e.getValue(),4096,67108864,16777216,()->{});var expected=object(object(object(profile.get("sources")).get(e.getKey())).get("source_members"));require(tree.keySet().equals(expected.keySet()),"Complete original source population differs: "+e.getKey());Path target=Files.createDirectory(captured.resolve(e.getKey()));
                    for(var member:tree.entrySet()){require(member.getValue().kind().equals("file")&&member.getValue().pin().equals(NextflowFiles.fingerprint(expected.get(member.getKey()),16777216)),"Pinned original source differs: "+e.getKey()+"/"+member.getKey());Path p=target.resolve(member.getKey());Files.createDirectories(p.getParent());Files.copy(e.getValue().resolve(member.getKey()),p);same(p,member.getValue().pin());}sources.put(e.getValue(),tree);
                }
                Files.createDirectory(out.resolve("inputs"));var inputs=new LinkedHashMap<Path,NextflowFiles.Pin>();long total=0;
                for(var e:Map.of("expression.data",r.expression(),"cells.tsv",r.cells(),"genes.tsv",r.genes()).entrySet()){var pin=NextflowFiles.pin(e.getValue(),r.inputBytes(),()->{});total=Math.addExact(total,pin.bytes());require(total<=r.inputBytes(),"Complete input byte capacity exceeded");inputs.put(e.getValue(),pin);Files.copy(e.getValue(),out.resolve("inputs").resolve(e.getKey()));same(out.resolve("inputs").resolve(e.getKey()),pin);}
                var population=Monocle131ModelInputs.read(out.resolve("inputs/expression.data"),out.resolve("inputs/cells.tsv"),out.resolve("inputs/genes.tsv"),r.format(),r.units(),r.types(),r.entries());
                var runtime=new LinkedHashMap<Path,Map<String,NextflowFiles.Entry>>();
                for(String name:List.of("monocle3","batchelor","GenomeInfoDbData","uwot","igraph","leidenbase","BiocNeighbors","BiocSingular","irlba","limma","Matrix"))for(Path lib:r.libraries()){Path p=lib.resolve(name);if(Files.isDirectory(p)){runtime.put(p,NextflowFiles.tree(p,8192,268435456,134217728,()->{}));break;}}
                var rscriptPin=NextflowFiles.pin(r.rscript(),16777216,()->{});NextflowFiles.writeJson(out.resolve("parameters.json"),r.parameters());Files.write(out.resolve("worker.R"),resource("worker.R"),StandardOpenOption.CREATE_NEW);Files.write(out.resolve("source-profile.json"),resource("source-profile.json"),StandardOpenOption.CREATE_NEW);
                var runtimeRows=new LinkedHashMap<String,Object>();for(var e:runtime.entrySet())runtimeRows.put(e.getKey().toString(),NextflowFiles.manifest(e.getValue()));NextflowFiles.writeJson(out.resolve("runtime-provenance.json"),Map.of("rscript",r.rscript().toString(),"rscript_pin",rscriptPin,"libraries",r.libraries().stream().map(Path::toString).toList(),"runtime_packages",runtimeRows,"producer_authenticated",false));
                Path bundle=out;var before=NextflowFiles.tree(out,20000,r.outputBytes(),r.outputBytes(),()->{});
                NextflowProcess.Check integrity=()->{same(request,requestPin);for(var e:inputs.entrySet())same(e.getKey(),e.getValue());same(r.rscript(),rscriptPin);for(var e:sources.entrySet())require(NextflowFiles.tree(e.getKey(),4096,67108864,16777216,()->{}).equals(e.getValue()),"Original source changed during analysis: "+e.getKey());for(var e:runtime.entrySet())require(NextflowFiles.tree(e.getKey(),8192,536870912,134217728,()->{}).equals(e.getValue()),"Original runtime changed during analysis: "+e.getKey());for(var e:before.entrySet())if(e.getValue().kind().equals("file"))same(bundle.resolve(e.getKey()),e.getValue().pin());};
                var prefix=r.rscript().getParent().getParent();var env=new LinkedHashMap<String,String>();env.put("PATH",prefix.resolve("bin")+":/usr/bin:/bin");env.put("R_HOME",prefix.resolve("lib/R").toString());env.put("LD_LIBRARY_PATH",prefix.resolve("lib").toString());env.put("R_ENVIRON_USER","/dev/null");env.put("R_PROFILE_USER","/dev/null");env.put("LANG","C.UTF-8");env.put("LC_ALL","C.UTF-8");for(String key:List.of("OMP_NUM_THREADS","OPENBLAS_NUM_THREADS","MKL_NUM_THREADS"))env.put(key,"1");var command=new ArrayList<>(List.of(r.rscript().toString(),"--vanilla",out.resolve("worker.R").toString(),out.toString(),captured.resolve("monocle3").toString(),captured.resolve("batchelor").toString()));command.addAll(r.libraries().stream().map(Path::toString).toList());
                try{NfcoreProcess.executeSession(command,env,out.resolve("process"),out,out,new NextflowProcess.Limits(r.seconds()*1000L,r.addressSpaceBytes(),r.seconds(),r.outputBytes(),1024,r.outputBytes(),20000,64,256,r.sampledRssBytes(),200),integrity,()->{});}catch(IOException failure){String detail=Files.isRegularFile(out.resolve("worker-error.txt"))?NextflowFiles.utf8(NextflowFiles.bytes(out.resolve("worker-error.txt"),65536)).strip():failure.toString();if(Files.isRegularFile(out.resolve("worker-exit.txt"))&&Files.readString(out.resolve("worker-exit.txt")).strip().equals("3"))throw new Skipped("Original runtime unavailable: "+detail);throw new IOException("Original pipeline failed: "+detail+"; retain diagnostics and unadmitted-last-cds.rds",failure);}
                integrity.verify();var original=read(out.resolve("worker-result.json"),r.jsonBytes());require(text(original.get("status")).equals("PASS_ORIGINAL_MONOCLE137_BATCHELOR120_COMPLETE_PIPELINE_REQUIRED_STATE")&&bool(original.get("complete_required_model_roundtrip")),"Original complete pipeline/model checks failed");var originalWarnings=NextflowFiles.strings(original.get("warnings"));originalWarningText="\n\n## Original warnings ("+originalWarnings.size()+")\n\n"+(originalWarnings.isEmpty()?"None returned during the original pipeline.":String.join("\n\n",originalWarnings));
                var ledger=read(out.resolve("population.json"),r.jsonBytes());require(NextflowFiles.strings(ledger.get("cell_ids")).equals(population.cells())&&NextflowFiles.strings(ledger.get("gene_ids")).equals(population.genes()),"Original/native complete expression axes differ");var alignment=read(out.resolve("alignment.json"),r.jsonBytes());require(NextflowFiles.strings(alignment.get("cell_ids")).equals(population.cells()),"Aligned cell axis differs from complete captured population");
                int dim=(int)integer(ledger.get("preprocessing_dimensions"),1,1024);require(integer(ledger.get("aligned_dimensions"),1,1024)==dim,"Alignment changed the declared preprocessing dimension");checkMatrix(alignment.get("before_alignment"),population.cells().size(),dim);checkMatrix(alignment.get("aligned"),population.cells().size(),dim);int umap=(int)integer(ledger.get("umap_dimensions"),2,1024);require(umap==integer(object(r.parameters().get("reduction")).get("max_components"),2,1024),"Original UMAP dimension differs");checkMatrix(ledger.get("umap"),population.cells().size(),umap);
                for(String key:List.of("clusters","partitions","size_factors"))require(list(ledger.get(key)).size()==population.cells().size(),"Incomplete original cell ledger: "+key);
                var learned=NextflowFiles.pin(out.resolve("principal-graph.json"),r.jsonBytes(),()->{});if(m.containsKey("expected_principal_graph_sha256"))require(learned.sha256().equals(text(m.get("expected_principal_graph_sha256"))),"Refitted principal graph differs from caller-declared prior graph");
                if(r.mode().equals("RUN")){var graph=read(out.resolve("prepared-graph.json"),r.jsonBytes());require(NextflowFiles.strings(graph.get("cell_ids")).equals(population.cells()),"Ordered graph cell population differs");require(graph.get("cell_coordinates").equals(ledger.get("umap")),"Ordered graph coordinates differ from learned UMAP");NextflowFiles.writeJson(out.resolve("native-audit.json"),Monocle137GraphAudit.audit(graph,r.operations()));result=true;}
                integrity.verify();pipeline=true;cause=result?"PASS_ORIGINAL_MONOCLE137_BATCHELOR120_PIPELINE_AND_NATIVE_ORDERING":"PASS_ORIGINAL_MONOCLE137_BATCHELOR120_LEARN_ONLY_NO_PSEUDOTIME";code=0;
            }
        }catch(Skipped|NextflowProcess.Unavailable e){cause="SKIP3: "+e;code=3;}catch(Exception e){cause="FAIL2: "+e;code=2;}catch(OutOfMemoryError e){cause="FAIL2: Java heap exhausted; no partial result admitted";code=2;}
        if(code!=0){pipeline=false;result=false;}
        try{if(owned){Files.writeString(out.resolve("WARNINGS.md"),"# "+cause+"\n\n"+SCOPE+"\n\n"+ACTION+"\n\nOriginal warnings/messages are retained in worker-result.json or worker-error.txt. The full supplied expression is retained unchanged; original selected preprocessing and Size_Factor estimation are applied afterwards. Original residual-alignment NA-coefficient handling and seed reset remain source behavior."+originalWarningText+"\n",StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);NextflowFiles.writeJson(out.resolve("analysis-status.json"),Map.of("status",cause,"exit_code",code,"pipeline_admitted",pipeline,"result_admitted",result,"required_action",ACTION,"whole_tool_qualified",false,"whole_goal_complete",false));}}catch(IOException e){cause="FAIL2: Cannot write complete status/warnings: "+e;code=2;}
        (code==0?stdout:stderr).println(cause+(out==null?"":"\nOutput: "+out));stderr.println("WARNINGS / "+ACTION);return code;
    }
    private static void checkMatrix(Object value,int rows,int columns)throws IOException{var matrix=Monocle137GraphAudit.matrix(value);require(matrix.length==rows,"Incomplete complete coordinate population");for(double[] row:matrix)require(row.length==columns,"Ragged complete coordinates");}
    private static Map<String,Object> read(Path p,int maximum)throws IOException{return object(NextflowParameters.parse(NextflowFiles.utf8(NextflowFiles.bytes(p,maximum)),maximum,20000000));}
    private static byte[] resource(String name)throws IOException{try(var in=Monocle137WorkflowCli.class.getResourceAsStream(RESOURCE+name)){if(in==null)throw new IOException("Missing packaged worker/profile: "+name);return in.readAllBytes();}}
    private static void same(Path path,NextflowFiles.Pin pin)throws IOException{require(pin.equals(NextflowFiles.pin(path,pin.bytes(),()->{})),"Captured input/source/runtime changed: "+path);}
    private static void newOutput(Path out,List<Path> paths)throws IOException{require(!Files.exists(out,LinkOption.NOFOLLOW_LINKS),"Output must be NEW; retain previous attempts");NextflowFiles.directory(out.getParent());for(Path path:paths)require(!out.startsWith(path)&&!path.startsWith(out),"Output overlaps protected input/source/runtime");Files.createDirectory(out);}
}
